# -*- coding: utf-8 -*-
import base64
import streamlit.web.cli as stcli
import sys

cifrado_data = ""

try:
    decodificado = base64.b64decode(cifrado_data).decode("utf-8")
    exec(compile(decodificado, "<string>", "exec"))
except Exception as e:
    print(f"Error al iniciar el sistema protegido: {e}")
